 const skills={"nobby": {"name": "Street distraction", "effect": "distract", "cue": "shove", "detail": "Distract one suspect: shaken, −1 resolve. Opens a later adjacent arrest."}, "colon": {"name": "Cover your colleague", "effect": "cover", "cue": "guard", "detail": "Guard yourself and an adjacent active colleague until each officer’s next turn."}, "detritus": {"name": "Piecemaker warning", "effect": "warning", "cue": "guard", "detail": "Spread the normal talk-down resolve across active suspects. No shot fired."}, "visit": {"name": "Persistent appeal", "effect": "appeal", "cue": "guard", "detail": "Spread your normal talk-down resolve across active suspects through persistent explanation."}, "reg": {"name": "Stand your ground", "effect": "stand", "cue": "guard", "detail": "Guard yourself and reduce one suspect’s resolve by 2. No healing or resurrection."}, "cheery": {"name": "Spot an opening", "effect": "opening", "cue": "guard", "detail": "Observe an active suspect: remove their guard and shake them. No automatic verdict."}, "dorfl": {"name": "Measured pin", "effect": "pin", "cue": "restrain", "detail": "Shake an adjacent suspect without pushing; guard yourself. Arrest needs another action."}, "angua": {"name": "Intercept", "effect": "intercept", "cue": "shove", "detail": "Use a legal route and remaining movement to reach a suspect and shake them. No transformation."}, "sally": {"name": "Read the movement", "effect": "read", "cue": "guard", "detail": "Watch an adjacent suspect: remove their guard, reduce resolve by 1 and guard yourself."}, "carrot": {"name": "Commanding appeal", "effect": "command", "cue": "guard", "detail": "Use your normal talk-down strength on one suspect and guard an adjacent active colleague."}};
